"""Turns lavora/brand.py into installer/brand.iss.inc so the installer and the app share one source of truth.

Run from the project folder:  python tools/make_brand.py
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)
from lavora import __version__, brand  # noqa: E402


def main():
    lines = [
        "; generated by tools/make_brand.py from lavora/brand.py - do not edit",
        f'#define AppName "{brand.NAME}"',
        f'#define AppPublisher "{brand.PUBLISHER}"',
        f'#define AppCopyright "{brand.COPYRIGHT}"',
        f'#define AppExe "{brand.GUI_EXE}"',
        f'#define CliExe "{brand.CLI_EXE}"',
        f'#define AppGuid "{{{brand.APP_ID}}}"',
        f'#define AppIdSetup "{{{{{brand.APP_ID}}}"',  # [Setup] AppId needs the opening brace doubled
        f'#define AppUrl "{brand.URL_HOME}"',
        f'#define AppSupportUrl "{brand.URL_SUPPORT}"',
        f'#define DefaultVersion "{__version__}"',
    ]
    path = os.path.join(ROOT, "installer", "brand.iss.inc")
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    print("wrote", path)


if __name__ == "__main__":
    main()
